# GH is the root namespace for new code that is shared across domain packages in the monolith.
module GH
  autoload :Associations, "gh/associations"
  autoload :Auth, "gh/auth"
  autoload :Context, "gh/context"
  autoload :Decorator, "gh/decorator"
  autoload :Domain, "gh/domain"
  autoload :Errors, "gh/errors"
  autoload :Interfaces, "gh/interfaces"
  autoload :Pagination, "gh/pagination"
  autoload :Result, "gh/result"

  sig { returns(Context) }
  def self.context
    Context.instance
  end

  sig { returns(Auth::IdentityContext) }
  def self.identity_context
    context.identity_context
  end
end
